python3 -c '
import urllib.request
import urllib.parse
from bs4 import BeautifulSoup

url = "https://html.duckduckgo.com/html/?q=" + urllib.parse.quote("site:apps.sfc.hk 26PR83")
req = urllib.request.Request(
    url, 
    headers={
        "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1"
    }
)
try:
    with urllib.request.urlopen(req) as response:
        html = response.read().decode("utf-8")
        soup = BeautifulSoup(html, "html.parser")
        for div in soup.find_all("div", class_="result__body"):
            snippet = div.find("a", class_="result__snippet")
            if snippet:
                print(snippet.get_text(strip=True))
except Exception as e:
    print("Error:", e)
'

